import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%87%E3%83%BC%E3%82%BF%E5%9C%A7%E7%B8%AE.html","title":"データ圧縮","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.07,"words":322},"filePathRelative":"データ圧縮.md"}`),a={name:`データ圧縮.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="データ圧縮" tabindex="-1"><a class="header-anchor" href="#データ圧縮"><span>データ圧縮</span></a></h1><p><a href="./CoverAndThomas.html">CoverAndThomas</a>の5章を中心にまとめる。<a href="./アルゴリズム.html">アルゴリズム</a></p><p><a href="https://karino2.github.io/2019/02/10/144121.html" target="_blank" rel="noopener noreferrer">Elements of Information Theoryの三章〜八章 - なーんだ、ただの水たまりじゃないか</a> の5章に詳しいメモがある。</p><h2 id="source-code" tabindex="-1"><a class="header-anchor" href="#source-code"><span>Source Code</span></a></h2><p>あるRandom Variable Xに対し、D種類のアルファベットをつなげた有限の文字列D*を対応させる。この対応させた文字列をsource codeという。</p><p>あるXの値xに対して、C(x)で対応するコードの文字列（codeword）を表すとしこのC(x)の長さをl(x)で表す。</p><p>圧縮で議論されるのは、このlの期待値L(C)。</p><h3 id="nonsingular" tabindex="-1"><a class="header-anchor" href="#nonsingular"><span>Nonsingular</span></a></h3><p>コードがnonsingularであるとは、Cが単射である事。（違うxが同じコードにならない）</p><h3 id="uniquely-decodable" tabindex="-1"><a class="header-anchor" href="#uniquely-decodable"><span>Uniquely Decodable</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">C(x1x2x3...) = C(x1)C(x2)...</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>と定義した時（これをextensionと言う）、これがnonsingularな事をuniquely decodableと呼ぶ。</p><h3 id="prefix-code-instantaneous-codeとも言う" tabindex="-1"><a class="header-anchor" href="#prefix-code-instantaneous-codeとも言う"><span>Prefix Code（instantaneous codeとも言う）</span></a></h3><p>どのcodewordも他のcodewordのprefixになってないコードをPrefix Codeと言う。これは一致した瞬間にそれより後ろを見ずjにcodewordが決定するという事。</p><h2 id="kraftの不等式-5-2" tabindex="-1"><a class="header-anchor" href="#kraftの不等式-5-2"><span>Kraftの不等式(5.2)</span></a></h2><p>任意のprefix codeは、以下の式を満たす。</p><p><img src="/RandomThoughts/assets/0000-BBpHN7Qx.png" alt="imgs/DataCompress/0000.png"></p><h3 id="証明のメモ" tabindex="-1"><a class="header-anchor" href="#証明のメモ"><span>証明のメモ</span></a></h3><p>上のツリーを参照。prefix codeという条件は、あるコードが他のコードの親になってない、という事なので、何かのコードワードになっていたら、その子どもは全部無いものとして考えられる。</p><p>式5.7は、あるシンボルのコードの長さがliとして、その下にlmaxまでの仮想的な足を全部生やすといくつになるか、という風に考える。 これが5.7式のシグマの中。</p><p>子どもが全部居たとしてもそれはlmaxまでの木の部分木のはずなので、それらを全部足してもレベルlmaxまでの木の葉の数よりは小さくなる。 これが式5.7の意味。</p><h2 id="最適コードの理論限界-5-3" tabindex="-1"><a class="header-anchor" href="#最適コードの理論限界-5-3"><span>最適コードの理論限界（5.3）</span></a></h2><p>クラフトの不等式を制約条件に期待長を最小化する問題をラグランジュの未定乗数法で解く。 すると5.19で最小となり、期待長は5.20となる。</p><p>また逆に、長さがliの時の期待長LとHの差分を直接計算すると、定理5.3.1の証明の式が得られる。 なお、Relative Entropyというのは<a href="./KLダイバージェンス.html">KLダイバージェンス</a>の事。</p><p>これらは実数での最適値なのでbitなどで表すなら端数の分これより少し長くなる。</p><h2 id="誤った分布の予測に基づくコードのコスト-定理5-4-3" tabindex="-1"><a class="header-anchor" href="#誤った分布の予測に基づくコードのコスト-定理5-4-3"><span>誤った分布の予測に基づくコードのコスト(定理5.4.3)</span></a></h2><p><img src="/RandomThoughts/assets/0001-Ct7VzPYt.png" alt="imgs/DataCompress/0001.png"></p><h2 id="ハフマンコード" tabindex="-1"><a class="header-anchor" href="#ハフマンコード"><span>ハフマンコード</span></a></h2><p>分布が分かっている時の最適な符号化法。分かっていないケース＞<a href="./LempelZiv.html">LempelZiv</a></p><p>一番確率が低い二つのシンボルに下位0と1を割り当ててマージして新しいシンボルとし、その新しいシンボルを含めた確率が一番低い2つをまた次の下位2ビットを与えてマージし…を繰り返して得られるコード。</p>`,30)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};